static char *
create_temp_file (const char *content,
                  size_t      size)
{
        char *filename = strdup ("/tmp/test-XXXXXX");
        int fd = mkstemp (filename);
        assert (fd != -1);
        assert (write (fd, content, size) == (ssize_t) size);
        close (fd);
        return filename;
}

static itty_bit_string_t *
create_bit_string (size_t word)
{
        itty_bit_string_t *bit_string = itty_bit_string_new (ITTY_BIT_STRING_MUTABILITY_READ_WRITE);
        itty_bit_string_append_word (bit_string, word);
        return bit_string;
}

static itty_bit_string_t *
create_zero_bit_string_with_words (size_t word_count)
{
        itty_bit_string_t *bit_string = itty_bit_string_new (ITTY_BIT_STRING_MUTABILITY_READ_WRITE);

        for (size_t word_index = 0; word_index < word_count; word_index++)
                itty_bit_string_append_word (bit_string, 0);

        return bit_string;
}

static void
clear_bit_string_words (itty_bit_string_t *bit_string)
{
        size_t *words;
        size_t word_count;

        assert (bit_string != NULL);
        words = itty_bit_string_get_words (bit_string);
        word_count = itty_bit_string_get_number_of_words (bit_string);
        memset (words, 0, word_count * sizeof (*words));
}

static void
mark_bit_string_bit (itty_bit_string_t *bit_string,
                     size_t             bit_index)
{
        size_t *words;
        size_t word_index;
        size_t bit_offset;

        assert (bit_string != NULL);
        assert (bit_index < itty_bit_string_get_length (bit_string));

        words = itty_bit_string_get_words (bit_string);
        word_index = bit_index / ITTY_BIT_STRING_WORD_SIZE_IN_BITS;
        bit_offset = bit_index % ITTY_BIT_STRING_WORD_SIZE_IN_BITS;
        words[word_index] |= ((size_t) 1 << bit_offset);
}

static void
or_bit_strings (itty_bit_string_t       *destination,
                itty_bit_string_t const *source)
{
        size_t *destination_words;
        size_t *source_words;
        size_t destination_word_count;
        size_t source_word_count;
        size_t word_count;

        assert (destination != NULL);
        assert (source != NULL);

        destination_words = itty_bit_string_get_words (destination);
        source_words = itty_bit_string_get_words ((itty_bit_string_t *) source);
        destination_word_count = itty_bit_string_get_number_of_words (destination);
        source_word_count = itty_bit_string_get_number_of_words ((itty_bit_string_t *) source);
        word_count = destination_word_count < source_word_count ? destination_word_count : source_word_count;

        for (size_t word_index = 0; word_index < word_count; word_index++)
                destination_words[word_index] |= source_words[word_index];
}

static itty_vocabulary_t *
create_vocabulary (char **text_file,
                   char **bit_string_file)
{
        const char *text_content = " a\n b\n";
        size_t bit_string_words[] = { 0b0011, 0b1100 };

        *text_file = create_temp_file (text_content, strlen (text_content));
        *bit_string_file = create_temp_file ((char *) bit_string_words, sizeof (bit_string_words));

        return itty_vocabulary_new (*text_file, *bit_string_file);
}

static bool measure_output_activation_for_node (itty_feed_model_t      *model,
                                                itty_bit_string_list_t *input,
                                                size_t                  node_index,
                                                itty_bit_string_t     **activation_out);

static itty_bit_string_list_t *
create_input (void)
{
        itty_bit_string_list_t *input = itty_bit_string_list_new ();
        itty_bit_string_list_append (input, create_bit_string (0b0011));
        return input;
}

static itty_bit_string_list_t *
create_input_with_count (size_t count,
                         size_t word)
{
        itty_bit_string_list_t *input = itty_bit_string_list_new ();

        for (size_t i = 0; i < count; i++)
                itty_bit_string_list_append (input, create_bit_string (word));

        return input;
}

typedef struct {
        size_t a_selected_route;
        size_t a_selected_gap;
        size_t b_selected_route;
        size_t b_selected_gap;
} route_key_selection_summary_t;

typedef struct {
        size_t threshold;
        bool   measured;
        size_t regressions;
        size_t total_distance;
        size_t total_excess;
        size_t d_selected_node;
        size_t d_selected_gap;
        itty_feed_model_decoder_objective_t objectives[4];
} within_node_threshold_sweep_summary_t;

typedef struct {
        size_t threshold;
        bool   measured;
        size_t fixed_node;
        size_t selected_node;
        size_t node1_popcount;
        size_t node6_popcount;
        ptrdiff_t node1_vs_node6_gap;
        itty_feed_model_decoder_objective_t node1_objective;
} fixed_node_threshold_sweep_summary_t;

static int
compare_within_node_threshold_sweep_summary (void const *left_ptr,
                                             void const *right_ptr)
{
        within_node_threshold_sweep_summary_t const *left = left_ptr;
        within_node_threshold_sweep_summary_t const *right = right_ptr;

        if (left->measured != right->measured)
                return left->measured ? -1 : 1;
        if (left->regressions != right->regressions)
                return left->regressions < right->regressions ? -1 : 1;
        if (left->objectives[3].selected_distance != right->objectives[3].selected_distance)
                return left->objectives[3].selected_distance < right->objectives[3].selected_distance ? -1 : 1;
        if (left->objectives[3].false_negative_vote_deficit != right->objectives[3].false_negative_vote_deficit)
                return left->objectives[3].false_negative_vote_deficit < right->objectives[3].false_negative_vote_deficit ? -1 : 1;
        if (left->objectives[3].false_positive_vote_excess != right->objectives[3].false_positive_vote_excess)
                return left->objectives[3].false_positive_vote_excess < right->objectives[3].false_positive_vote_excess ? -1 : 1;
        if (left->d_selected_gap != right->d_selected_gap)
                return left->d_selected_gap > right->d_selected_gap ? -1 : 1;
        if (left->total_distance != right->total_distance)
                return left->total_distance < right->total_distance ? -1 : 1;
        if (left->total_excess != right->total_excess)
                return left->total_excess < right->total_excess ? -1 : 1;
        if (left->threshold != right->threshold)
                return left->threshold < right->threshold ? -1 : 1;
        return 0;
}

static bool
gray_probe_triplet_improves (itty_feed_model_decoder_objective_t const *candidate,
                             itty_feed_model_decoder_objective_t const *baseline)
{
        if (candidate->selected_distance != baseline->selected_distance)
                return candidate->selected_distance < baseline->selected_distance;
        if (candidate->false_negative_vote_deficit != baseline->false_negative_vote_deficit)
                return candidate->false_negative_vote_deficit < baseline->false_negative_vote_deficit;
        if (candidate->false_positive_vote_excess != baseline->false_positive_vote_excess)
                return candidate->false_positive_vote_excess < baseline->false_positive_vote_excess;
        return false;
}

static int
compare_fixed_node_threshold_sweep_summary (void const *left_ptr,
                                            void const *right_ptr)
{
        fixed_node_threshold_sweep_summary_t const *left = left_ptr;
        fixed_node_threshold_sweep_summary_t const *right = right_ptr;

        if (left->measured != right->measured)
                return left->measured ? -1 : 1;
        if (left->node1_objective.selected_distance != right->node1_objective.selected_distance)
                return left->node1_objective.selected_distance < right->node1_objective.selected_distance ? -1 : 1;
        if (left->node1_objective.false_negative_vote_deficit != right->node1_objective.false_negative_vote_deficit)
                return left->node1_objective.false_negative_vote_deficit < right->node1_objective.false_negative_vote_deficit ? -1 : 1;
        if (left->node1_objective.false_positive_vote_excess != right->node1_objective.false_positive_vote_excess)
                return left->node1_objective.false_positive_vote_excess < right->node1_objective.false_positive_vote_excess ? -1 : 1;
        if (left->node1_vs_node6_gap != right->node1_vs_node6_gap)
                return left->node1_vs_node6_gap > right->node1_vs_node6_gap ? -1 : 1;
        if (left->threshold != right->threshold)
                return left->threshold < right->threshold ? -1 : 1;
        return 0;
}

typedef struct {
        size_t a_selected_route;
        size_t a_selected_gap;
        size_t b_selected_route;
        size_t b_selected_gap;
        size_t c_selected_route;
        size_t c_selected_gap;
} route_key_selection_summary_abc_t;

typedef struct {
        size_t selected_route;
        size_t selected_gap;
        size_t nearest_competing_route;
} route_key_probe_summary_t;

static route_key_selection_summary_t
measure_route_key_selection (itty_bit_string_t **route_keys,
                             size_t              nodes,
                             itty_bit_string_t  *a_probe,
                             itty_bit_string_t  *b_probe)
{
        route_key_selection_summary_t summary = { 0 };
        size_t a_selected_score = 0;
        size_t b_selected_score = 0;
        size_t a_runner_up_score = 0;
        size_t b_runner_up_score = 0;

        for (size_t route = 0; route < nodes; route++) {
                size_t a_score = itty_bit_string_evaluate_similarity (a_probe, route_keys[route]);
                size_t b_score = itty_bit_string_evaluate_similarity (b_probe, route_keys[route]);

                if (route == 0 || a_score > a_selected_score) {
                        a_runner_up_score = a_selected_score;
                        a_selected_score = a_score;
                        summary.a_selected_route = route;
                } else if (a_score > a_runner_up_score) {
                        a_runner_up_score = a_score;
                }

                if (route == 0 || b_score > b_selected_score) {
                        b_runner_up_score = b_selected_score;
                        b_selected_score = b_score;
                        summary.b_selected_route = route;
                } else if (b_score > b_runner_up_score) {
                        b_runner_up_score = b_score;
                }
        }

        summary.a_selected_gap = a_selected_score - a_runner_up_score;
        summary.b_selected_gap = b_selected_score - b_runner_up_score;
        return summary;
}

static route_key_selection_summary_abc_t
measure_route_key_selection_abc (itty_bit_string_t **route_keys,
                                 size_t              nodes,
                                 itty_bit_string_t  *a_probe,
                                 itty_bit_string_t  *b_probe,
                                 itty_bit_string_t  *c_probe)
{
        route_key_selection_summary_abc_t summary = { 0 };
        size_t a_selected_score = 0;
        size_t b_selected_score = 0;
        size_t c_selected_score = 0;
        size_t a_runner_up_score = 0;
        size_t b_runner_up_score = 0;
        size_t c_runner_up_score = 0;

        for (size_t route = 0; route < nodes; route++) {
                size_t a_score = itty_bit_string_evaluate_similarity (a_probe, route_keys[route]);
                size_t b_score = itty_bit_string_evaluate_similarity (b_probe, route_keys[route]);
                size_t c_score = itty_bit_string_evaluate_similarity (c_probe, route_keys[route]);

                if (route == 0 || a_score > a_selected_score) {
                        a_runner_up_score = a_selected_score;
                        a_selected_score = a_score;
                        summary.a_selected_route = route;
                } else if (a_score > a_runner_up_score) {
                        a_runner_up_score = a_score;
                }

                if (route == 0 || b_score > b_selected_score) {
                        b_runner_up_score = b_selected_score;
                        b_selected_score = b_score;
                        summary.b_selected_route = route;
                } else if (b_score > b_runner_up_score) {
                        b_runner_up_score = b_score;
                }

                if (route == 0 || c_score > c_selected_score) {
                        c_runner_up_score = c_selected_score;
                        c_selected_score = c_score;
                        summary.c_selected_route = route;
                } else if (c_score > c_runner_up_score) {
                        c_runner_up_score = c_score;
                }
        }

        summary.a_selected_gap = a_selected_score - a_runner_up_score;
        summary.b_selected_gap = b_selected_score - b_runner_up_score;
        summary.c_selected_gap = c_selected_score - c_runner_up_score;
        return summary;
}

static route_key_probe_summary_t
measure_route_key_selection_for_probe (itty_bit_string_t **route_keys,
                                       size_t              nodes,
                                       itty_bit_string_t  *probe)
{
        route_key_probe_summary_t summary = { 0 };
        size_t selected_score = 0;
        size_t runner_up_score = 0;

        for (size_t route = 0; route < nodes; route++) {
                size_t score = itty_bit_string_evaluate_similarity (probe, route_keys[route]);

                if (route == 0 || score > selected_score) {
                        runner_up_score = selected_score;
                        summary.nearest_competing_route = summary.selected_route;
                        selected_score = score;
                        summary.selected_route = route;
                } else if (score > runner_up_score) {
                        runner_up_score = score;
                        summary.nearest_competing_route = route;
                }
        }

        summary.selected_gap = selected_score - runner_up_score;
        return summary;
}

static bool
route_objective_not_worse_than_committed (itty_feed_model_decoder_objective_t const *after,
                                          itty_feed_model_decoder_objective_t const *committed)
{
        if (after->selected_distance > committed->selected_distance)
                return false;
        if (after->selected_distance < committed->selected_distance)
                return true;
        if (after->false_negative_vote_deficit > committed->false_negative_vote_deficit)
                return false;
        if (after->false_negative_vote_deficit < committed->false_negative_vote_deficit)
                return true;
        if (after->false_positive_vote_excess > committed->false_positive_vote_excess)
                return false;
        return true;
}

static bool
route_objective_improves_on_committed (itty_feed_model_decoder_objective_t const *after,
                                       itty_feed_model_decoder_objective_t const *committed)
{
        if (after->selected_distance < committed->selected_distance)
                return true;
        if (after->selected_distance > committed->selected_distance)
                return false;
        if (after->false_negative_vote_deficit < committed->false_negative_vote_deficit)
                return true;
        if (after->false_negative_vote_deficit > committed->false_negative_vote_deficit)
                return false;
        return after->false_positive_vote_excess < committed->false_positive_vote_excess;
}

#define GRAY_MCTS_MAX_NODES 4096
#define GRAY_MCTS_MAX_PATH  128

