        case ITTY_FEED_MODEL_SEGMENT_TRAIN_STOP_NO_EFFECTIVE_CANDIDATES:
                return "no-effective-candidates";
        case ITTY_FEED_MODEL_SEGMENT_TRAIN_STOP_NO_PROGRESS:
