        size_t no_progress_runs = 0;
        size_t total_flips = 0;
        size_t total_distance_before = 0;
        size_t total_distance_after = 0;
        size_t total_deficit_before = 0;
        size_t total_deficit_after = 0;
        size_t no_effect_candidates = 0;
