                                                        assert (itty_feed_model_train_final_layer_with_suffix_oracle_for_node_mode (decoder_model,
                                                                                                                                    inputs[replay_index],
                                                                                                                                    targets[replay_index],
                                                                                                                                    step->target_node,
                                                                                                                                    &step_options,
                                                                                                                                    step->mode,
                                                                                                                                    &step_stats,
                                                                                                                                    &step_summary));
