        printf ("---d_conflict_internal_switch_harmful=%zu\n", d_conflict.internal_switch_harmful);
        printf ("---d_conflict_accepted=%zu\n", d_conflict.accepted_count);
        printf ("---d_conflict_rejected=%zu\n", d_conflict.rejected_count);
